<script setup lang="ts">import {ref,computed,onMounted,watch} from 'vue';import {route} from '../router';import {batches} from '../stores/batches';import {items} from '../stores/items';import {canWrite} from '../stores/auth';import {itemSides,sideLabels} from '../constants/enums';import {money} from '../utils/format';import {useTask} from '../hooks/useTask';import PageHeading from '../components/common/PageHeading.vue';import Notice from '../components/common/Notice.vue';import UnmatchedTable from '../components/UnmatchedTable.vue';const batch=ref(route.value.query.get('batch')||'demo-batch'),filter=ref('all'),ident=ref(''),side=ref('milestone'),party=ref(''),reference=ref(''),amount=ref(10000),day=ref('2026-11-01');const {error,busy,act}=useTask();onMounted(async()=>{await batches.load();await items.load(batch.value)});watch(batch,()=>items.load(batch.value));watch(()=>route.value.query.get('batch'),v=>{batch.value=v||'demo-batch'});const rows=computed(()=>items.rows.value.filter(r=>filter.value==='all'||r.side===filter.value));function submit(){act(async()=>{await items.create({batch_id:batch.value,external_id:ident.value,side:side.value,party:party.value,reference:reference.value,amount_cents:amount.value,currency:'CNY',booking_date:day.value});ident.value=''})}</script><template><PageHeading index="02 / 委托与凭证" title="每一笔金额，都能回到原始分录。" note="录入仅接受整数分，显示可格式化为元但不参与金额转换。补录会改变后续运行的输入快照，不修改既有报告。"/><div class="two-col"><section><div class="item-controls"><label>对账批次<select v-model="batch"><option v-for="r in batches.items.value" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label>方向<select v-model="filter"><option value="all">全部分录</option><option v-for="s in itemSides" :key="s" :value="s">{{sideLabels[s]}}</option></select></label></div><p class="method-note">当前显示{{rows.length}}条 / 批次共{{items.rows.value.length}}条；金额CNY。</p><Notice :message="items.error.value"/><UnmatchedTable :rows="rows"/></section><form v-if="canWrite()" class="editor-panel" @submit.prevent="submit"><h2>补录模拟分录</h2><label>分录ID<input v-model="ident" required maxlength="80"></label><label>方向<select v-model="side"><option v-for="s in itemSides" :key="s" :value="s">{{sideLabels[s]}}</option></select></label><label>往来方<input v-model="party" required maxlength="160"></label><label>委托引用<input v-model="reference" maxlength="100"></label><label>金额（正整数分）<input type="number" v-model.number="amount" min="1" max="100000000" step="1" required></label><p class="amount-preview">仅显示：{{money(amount)}} 元 / CNY</p><label>业务日期<input type="date" v-model="day" required></label><Notice :message="error"/><button :disabled="busy">保存模拟分录</button></form></div></template>
